// Hand-written `knex` stub for the flowatlas fixture suite. It declares only what
// `fixtures/nest-knex/src` touches, shaped like the real library so that
// `resolveTypeOrigin` sees the same thing it sees on a real repo: the builder's type is
// declared in `node_modules/knex`, and it says nothing about which table it is for.
//
// That is the shape this fixture is here for. A knex query starts from the table and
// then chains: `knex('users').where({ id }).first()`. The call that carries the
// operation is the last one, and the table is in the call the chain started from, so
// the `knex` descriptor's locator walks back down the receivers to find it.

export interface QueryBuilder {
  from(table: string): QueryBuilder;
  where(condition: unknown): QueryBuilder;
  whereRaw(clause: string): QueryBuilder;
  orderBy(column: string): QueryBuilder;
  returning(column: string): Promise<unknown[]>;
  select(...columns: string[]): Promise<unknown[]>;
  first(): Promise<unknown>;
  count(column?: string): Promise<unknown>;
  insert(row: Record<string, unknown>): QueryBuilder;
  update(row: Record<string, unknown>): Promise<number>;
  del(): Promise<number>;
}

export interface KnexInstance {
  (table: string): QueryBuilder;
  select(...columns: string[]): QueryBuilder;
  count(column?: string): QueryBuilder;
  raw(sql: string): Promise<unknown>;
}

export declare const knex: (config?: unknown) => KnexInstance;
